CREATE OR REPLACE FUNCTION private.prepare_freight(_nota uuid,_motivo text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n notas_fiscais; f uuid; t tabelas_frete; km numeric; mem jsonb; calc uuid; st text; regras jsonb; BEGIN SELECT * INTO n FROM notas_fiscais WHERE id=_nota FOR UPDATE; IF EXISTS(SELECT 1 FROM financeiro WHERE nota_fiscal_id=_nota AND estado_frete IN ('conferido','pronto_faturamento','faturado')) THEN RAISE EXCEPTION 'Frete fechado: recálculo bloqueado'; END IF; SELECT id INTO f FROM fornecedores WHERE cnpj=regexp_replace(coalesce(n.cnpj_emissor,''),'\D','','g'); SELECT * INTO t FROM tabelas_frete WHERE fornecedor_id=f AND inicio<=coalesce(n.data_emissao,current_date) AND (fim IS NULL OR fim>=coalesce(n.data_emissao,current_date)) ORDER BY versao DESC,created_at DESC LIMIT 1; SELECT d.km INTO km FROM distancias d WHERE lower(trim(d.cidade))=lower(trim(n.cidade)) AND upper(d.uf)=upper(n.uf); IF t.id IS NULL OR NOT t.ativo THEN st:='sem_tabela'; mem:=jsonb_build_object('situacao',st,'total',NULL); ELSE regras:=t.regras; regras:=jsonb_set(regras,'{operacoes}',coalesce((SELECT jsonb_agg(op) FROM jsonb_array_elements(coalesce(regras->'operacoes','[]')) op WHERE (op->>'uf' IS NULL OR upper(op->>'uf')=upper(n.uf)) AND (op->>'cidade' IS NULL OR lower(op->>'cidade')=lower(n.cidade))),'[]')); SELECT coalesce(jsonb_agg(op-'uf'-'cidade'),'[]') INTO regras FROM jsonb_array_elements(regras->'operacoes') op; regras:=jsonb_set(t.regras,'{operacoes}',regras); mem:=public.simular_frete(regras,n.peso,n.valor,km); st:=mem->>'situacao'; END IF; mem:=mem||jsonb_build_object('origem','Teresina / PI','destino',n.cidade||' / '||coalesce(n.uf,''),'fornecedor',n.fornecedor,'tabela',t.nome,'versao',t.versao,'data_referencia',coalesce(n.data_emissao,current_date)); INSERT INTO calculos_frete(nota_id,tabela_id,situacao,total,memoria,motivo) VALUES(_nota,t.id,st,(mem->>'total')::numeric,mem,_motivo) RETURNING id INTO calc; UPDATE financeiro SET calculo_id=calc,estado_frete=CASE WHEN st='pre_calculado' THEN 'aguardando_conferencia' ELSE st END,valor_base=coalesce((mem->>'base')::numeric,0),valor_ad_valorem=coalesce((mem->>'ad_valorem')::numeric,0),valor_tributos=coalesce((mem->>'tributos')::numeric,0),valor_taxa_extra=coalesce((mem->>'adicionais')::numeric,0),valor_frete=coalesce((mem->>'total')::numeric,0),distancia=km WHERE nota_fiscal_id=_nota; RETURN calc; END $$;
REVOKE ALL ON FUNCTION private.prepare_freight(uuid,text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.recalcular_frete(_nota uuid,_motivo text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT private.can_finance(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF length(trim(_motivo))<3 THEN RAISE EXCEPTION 'Informe o motivo'; END IF; INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('nota',_nota,'frete_recalculado',_motivo,auth.uid()); RETURN private.prepare_freight(_nota,_motivo); END $$;
REVOKE ALL ON FUNCTION public.recalcular_frete(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.recalcular_frete(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.tg_nota_gera_financeiro() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.tg_auto_freight() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM private.prepare_freight(NEW.id,'Importação da NF'); RETURN NEW; END $$;
CREATE TRIGGER zz_prepare_freight AFTER INSERT ON notas_fiscais FOR EACH ROW EXECUTE FUNCTION public.tg_auto_freight();
CREATE OR REPLACE FUNCTION public.tg_proof_finance() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f uuid; calc uuid; BEGIN IF NEW.status='aprovado' AND OLD.status IS DISTINCT FROM 'aprovado' THEN IF NEW.tipo_documento<>'canhoto' THEN RAISE EXCEPTION 'Documento complementar não gera entrega'; END IF; SELECT id INTO f FROM fornecedores WHERE cnpj=(SELECT regexp_replace(cnpj_emissor,'\D','','g') FROM notas_fiscais WHERE id=NEW.nota_id); INSERT INTO financeiro(nota_fiscal_id,fornecedor_id,data_entrega,comprovante_id,entrega_id,estado_frete) VALUES(NEW.nota_id,f,NEW.data_entrega::date,NEW.id,NEW.entrega_id,'calculo_pendente') ON CONFLICT(nota_fiscal_id) DO UPDATE SET comprovante_id=EXCLUDED.comprovante_id,entrega_id=EXCLUDED.entrega_id,data_entrega=EXCLUDED.data_entrega WHERE financeiro.estado_frete NOT IN ('conferido','pronto_faturamento','faturado'); IF NOT EXISTS(SELECT 1 FROM financeiro WHERE nota_fiscal_id=NEW.nota_id AND estado_frete IN ('conferido','pronto_faturamento','faturado')) THEN calc:=private.prepare_freight(NEW.nota_id,'Aprovação pelo escritório'); END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER proof_finance AFTER UPDATE OF status ON comprovantes FOR EACH ROW EXECUTE FUNCTION public.tg_proof_finance();
CREATE OR REPLACE FUNCTION public.fechar_frete(_ids uuid[],_estado text,_motivo text,_ajuste numeric DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f financeiro; BEGIN IF NOT private.can_finance(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF _estado NOT IN ('conferido','pronto_faturamento','faturado') OR length(trim(_motivo))<3 THEN RAISE EXCEPTION 'Informe situação e justificativa'; END IF; FOR f IN SELECT * FROM financeiro WHERE id=ANY(_ids) ORDER BY id FOR UPDATE LOOP IF f.estado_frete='faturado' THEN RAISE EXCEPTION 'NF já faturada'; END IF; IF f.calculo_id IS NULL OR NOT EXISTS(SELECT 1 FROM calculos_frete WHERE id=f.calculo_id AND total IS NOT NULL) THEN RAISE EXCEPTION 'Cálculo incompleto'; END IF; IF _estado='pronto_faturamento' AND f.estado_frete<>'conferido' OR _estado='faturado' AND f.estado_frete<>'pronto_faturamento' THEN RAISE EXCEPTION 'Conferir e preparar antes de faturar'; END IF; UPDATE financeiro SET estado_frete=_estado,ajuste=coalesce(_ajuste,ajuste),valor_frete=valor_frete-coalesce(ajuste,0)+coalesce(_ajuste,ajuste),observacoes=_motivo WHERE id=f.id; INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('financeiro',f.id,'frete_'||_estado,_motivo,auth.uid()); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.fechar_frete(uuid[],text,text,numeric) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.fechar_frete(uuid[],text,text,numeric) TO authenticated;
CREATE OR REPLACE FUNCTION public.triar_documento(_id uuid,_tipo text,_situacao text,_obs text,_nota uuid DEFAULT NULL,_carga uuid DEFAULT NULL,_entrega uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT private.can_write(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF _tipo NOT IN ('canhoto','devolucao','recibo','recusa','outro','nao_identificado') OR _situacao NOT IN ('pendente','analisado','nova_foto') THEN RAISE EXCEPTION 'Classificação inválida'; END IF; UPDATE comprovantes SET tipo_documento=_tipo,triagem=_situacao,observacoes_documento=_obs WHERE id=_id AND status NOT IN ('aprovado','rejeitado'); IF NOT FOUND THEN RAISE EXCEPTION 'Documento já finalizado'; END IF; IF _nota IS NOT NULL OR _carga IS NOT NULL OR _entrega IS NOT NULL THEN INSERT INTO documento_vinculos(comprovante_id,nota_id,carga_id,entrega_id) VALUES(_id,_nota,_carga,_entrega); END IF; INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('comprovante',_id,'documento_triado',_tipo||' / '||_situacao||' / '||_obs,auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.triar_documento(uuid,text,text,text,uuid,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.triar_documento(uuid,text,text,text,uuid,uuid,uuid) TO authenticated;
CREATE POLICY active_roles_restriction ON public.user_roles AS RESTRICTIVE FOR SELECT TO authenticated USING(private.active_user(auth.uid()));
CREATE POLICY active_notes_restriction ON public.notas_fiscais AS RESTRICTIVE FOR ALL TO authenticated USING(private.active_user(auth.uid())) WITH CHECK(private.active_user(auth.uid()));
CREATE POLICY active_loads_restriction ON public.cargas AS RESTRICTIVE FOR ALL TO authenticated USING(private.active_user(auth.uid())) WITH CHECK(private.active_user(auth.uid()));
CREATE POLICY active_proofs_restriction ON public.comprovantes AS RESTRICTIVE FOR ALL TO authenticated USING(private.active_user(auth.uid())) WITH CHECK(private.active_user(auth.uid()));
